"""A production-quality memoize decorator."""

import functools
import inspect
import time
from typing import Any, Callable


class UnhashableArgumentError(TypeError):
    """Raised when a memoized function is called with unhashable arguments."""


def _make_key(args: tuple, kwargs: dict, sig: inspect.Signature) -> tuple:
    """Bind args/kwargs to the signature and return a hashable cache key.

    Raises TypeError naming the offending argument if any bound value is
    unhashable.
    """
    try:
        bound = sig.bind(*args, **kwargs)
        bound.apply_defaults()
    except TypeError:
        # Propagate genuine signature mismatches untouched.
        raise
    key_args = []
    for name, value in bound.arguments.items():
        try:
            hash(value)
        except TypeError:
            raise TypeError(
                f"unhashable argument {name!r} of type "
                f"{type(value).__name__!r} cannot be memoized"
            ) from None
        key_args.append((name, value))
    return tuple(key_args)


def memoize(func: Callable) -> Callable:
    """Memoize `func`, normalizing positional and keyword arguments.

    f(1, b=2) and f(b=2, a=1) share a cache slot for def f(a, b), because
    keys are built from inspect.signature binding (parameter name -> value).

    Attaches to the decorated function:
      - .cache_stats  -> dict with 'hits', 'misses', 'hits+misses' == calls
      - .cache_clear() -> empties the cache and resets stats
    """
    sig = inspect.signature(func)
    cache: dict = {}
    stats = {"hits": 0, "misses": 0}

    @functools.wraps(func)
    def wrapper(*args: Any, **kwargs: Any) -> Any:
        key = _make_key(args, kwargs, sig)
        try:
            result = cache[key]
        except KeyError:
            stats["misses"] += 1
            result = func(*args, **kwargs)
            cache[key] = result
        else:
            stats["hits"] += 1
        return result

    def cache_clear() -> None:
        cache.clear()
        stats["hits"] = 0
        stats["misses"] = 0

    wrapper.cache = cache
    wrapper.cache_stats = stats
    wrapper.cache_clear = cache_clear
    return wrapper

"""Tests for the memoize decorator."""

import time

import pytest

from memoize import UnhashableArgumentError, memoize


# --- basic behavior -------------------------------------------------------

def test_returns_same_result():
    calls = []

    @memoize
    def f(x):
        calls.append(x)
        return x * 2

    assert f(3) == 6
    assert f(3) == 6
    assert calls == [3]  # underlying called once


def test_distinct_functions_get_distinct_caches():
    @memoize
    def f(x):
        return "f"

    @memoize
    def g(x):
        return "g"

    assert f(1) == "f"
    assert g(1) == "g"
    # Neither pollutes the other's cache or stats.
    assert f.cache_stats == {"hits": 0, "misses": 1}
    assert g.cache_stats == {"hits": 0, "misses": 1}
    f.cache_clear()
    assert len(f.cache) == 0
    assert len(g.cache) == 1  # untouched


def test_cache_clear_resets_stats_and_cache():
    @memoize
    def f(x):
        return x

    f(1)
    f(1)
    assert f.cache_stats == {"hits": 1, "misses": 1}
    f.cache_clear()
    assert f.cache_stats == {"hits": 0, "misses": 0}
    assert len(f.cache) == 0
    assert f(1) == 1  # recomputed fine after clear
    assert f.cache_stats == {"hits": 0, "misses": 1}


# --- kwargs normalization -------------------------------------------------

def test_kwargs_normalization_shares_slot():
    @memoize
    def f(a, b):
        return a + b

    r1 = f(1, b=2)
    r2 = f(b=2, a=1)
    assert r1 == r2 == 3
    assert f.cache_stats["misses"] == 1
    assert f.cache_stats["hits"] == 1
    assert len(f.cache) == 1


def test_kwargs_normalization_with_defaults():
    @memoize
    def f(a, b=10):
        return a + b

    assert f(5) == f(a=5) == 15
    assert f.cache_stats["misses"] == 1  # both forms bind identically


# --- unhashable arguments --------------------------------------------------

def test_unhashable_positional_arg_raises_clear_typeerror():
    @memoize
    def f(a):
        return a

    with pytest.raises(UnhashableArgumentError) as exc:
        f([1, 2, 3])
    assert "'a'" in str(exc.value)


def test_unhashable_kwarg_raises_clear_typeerror():
    @memoize
    def f(a, b):
        return a + b

    with pytest.raises(UnhashableArgumentError) as exc:
        f(1, b={"x": 1})
    assert "'b'" in str(exc.value)


def test_hashable_call_still_works_after_unhashable_failure():
    @memoize
    def f(a):
        return a

    with pytest.raises(UnhashableArgumentError):
        f([])
    assert f(42) == 42
    assert f.cache_stats["misses"] == 1


# --- speed requirement ------------------------------------------------------

def fib_undecorated(n):
    return n if n < 2 else fib_undecorated(n - 1) + fib_undecorated(n - 2)


@memoize
def _fib(n):
    return n if n < 2 else _fib(n - 1) + _fib(n - 2)


def test_decorated_fib_at_least_100x_faster():
    n = 30
    start = time.perf_counter()
    expected = fib_undecorated(n)
    baseline = time.perf_counter() - start

    start = time.perf_counter()
    assert _fib(n) == expected
    decorated = time.perf_counter() - start

    speedup = baseline / decorated
    print(f"\nfib({n}): undecorated={baseline:.4f}s "
          f"decorated={decorated:.6f}s speedup={speedup:.1f}x")
    assert decorated * 100 <= baseline, (
        f"expected >=100x speedup, got {speedup:.1f}x"
    )


if __name__ == "__main__":
    raise SystemExit(pytest.main([__file__, "-v", "-s"]))

